// Datos de ejercicios (nombres en español, pasos traducidos del dataset hasaneyldrm/exercises-dataset, licencia MIT).
// [id, nombre, nombre original, nivel (0=estiramiento), tipo, músculo, pasos]
const CAT=[["0001","Abdominal de tres cuartos","3/4 sit-up",1,"abd","abdomen",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["0006","Toques alternos de talón","alternate heel touchers",1,"abd","abdomen",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Extiende los brazos hacia los lados, paralelos al suelo.","Activando el abdomen, levanta los hombros del suelo y lleva la mano derecha hacia el talón derecho.","Regresa a la posición inicial y repite del lado izquierdo, llevando la mano izquierda hacia el talón izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."]],["0262","Abdominal cruzado","cross body crunch",1,"abd","abdomen",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta la parte superior del cuerpo del suelo y gira para llevar el codo derecho hacia la rodilla izquierda.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite en el otro lado, llevando el codo izquierdo hacia la rodilla derecha.","Repite el número de repeticiones deseado."]],["0274","Abdominal en el piso","crunch floor",1,"abd","abdomen",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activa el abdomen y levanta los hombros del suelo, flexionándote hacia adelante en dirección a las rodillas.","Haz una pausa breve en la parte alta, luego baja lentamente los hombros de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["3016","Elevación corta de tronco","curl-up",1,"abd","abdomen",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["0276","Bicho muerto","dead bug",1,"abd","abdomen",["Túmbate boca arriba con los brazos extendidos hacia el techo.","Flexiona las rodillas y levanta las piernas del suelo, formando un ángulo de 90 grados en las caderas y las rodillas.","Activa el core y la zona lumbar para presionar la zona lumbar contra el suelo.","Baja lentamente el brazo derecho y la pierna izquierda hacia el suelo, manteniéndolos rectos y justo por encima del suelo.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite el movimiento con el brazo izquierdo y la pierna derecha.","Continúa alternando lados durante el número de repeticiones deseado."]],["0635","Abdominales oblicuos en el piso","oblique crunches floor",1,"abd","abdomen",["Túmbate boca arriba con las rodillas flexionadas y los pies planos en el suelo.","Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.","Activa el abdomen y levanta las escápulas del suelo, rotando el torso hacia un lado.","Haz una pausa por un momento y luego baja las escápulas de nuevo hasta el suelo.","Repite hacia el otro lado, alternando los lados en cada repetición."]],["3202","Medio abdominal","half sit-up (male)",1,"abd","abdomen",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["3201","Cuarto de abdominal","quarter sit-up",1,"abd","abdomen",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["0689","Elevación de pierna sentado","seated leg raise",1,"abd","abdomen",["Siéntate en un banco plano con la espalda recta y los pies planos sobre el suelo.","Coloca las manos a los lados del banco para apoyarte.","Manteniendo las piernas rectas, levántalas lentamente frente a ti hasta que queden paralelas al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["0691","Abdominal lateral sentado contra la pared","seated side crunch (wall)",1,"abd","abdomen",["Siéntate en el suelo con la espalda contra una pared y las piernas extendidas frente a ti.","Dobla las rodillas y coloca los pies planos sobre el suelo, separados a la altura de la cadera.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Contrae el abdomen e inclínate hacia un lado, llevando el codo hacia la cadera.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite del otro lado.","Continúa alternando lados durante el número de repeticiones deseado."]],["0624","Marcha sentado contra la pared","march sit (wall)",1,"abd","glúteos",["Ponte de pie con la espalda contra una pared y los pies separados a la altura de las caderas.","Desliza lentamente la espalda hacia abajo por la pared hasta que las rodillas formen un ángulo de 90 grados.","Levanta el pie derecho del suelo y lleva la rodilla hacia el pecho.","Baja el pie derecho de nuevo y levanta el pie izquierdo del suelo, llevando la rodilla hacia el pecho.","Continúa alternando entre levantar el pie derecho y el izquierdo el número de repeticiones deseado."]],["3147","Inclinación de pelvis","pelvic tilt",1,"abd","abdomen",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos a los lados del cuerpo.","Activa el abdomen e inclina la pelvis hacia arriba, presionando la zona lumbar contra el suelo.","Mantén esta posición durante unos segundos, concentrándote en contraer el abdomen.","Deshaz la inclinación y vuelve a la posición inicial.","Repite el número de repeticiones deseado."]],["1364","Inclinación de pelvis de pie","standing pelvic tilt",1,"abd","columna",["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Coloca las manos sobre las caderas o déjalas colgar a los lados.","Activa los músculos del core e inclina la pelvis hacia adelante, empujando la zona lumbar hacia la pared detrás de ti.","Mantén la posición durante unos segundos, luego suelta y vuelve a la posición inicial.","Repite el número de repeticiones deseado."]],["1422","Inclinación de pelvis hacia puente","pelvic tilt into bridge",1,"abd","glúteos",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca los brazos a los lados del cuerpo con las palmas hacia abajo.","Activa los glúteos y los músculos del core.","Inclina la pelvis hacia arriba, levantando las caderas del suelo.","Mantén la posición de puente durante unos segundos.","Baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["0003","Bicicleta en el aire","air bike",2,"abd","abdomen",["Túmbate sobre tu espalda con las manos colocadas detrás de la cabeza.","Levanta las piernas del suelo y flexiona las rodillas formando un ángulo de 90 grados.","Lleva el codo derecho hacia la rodilla izquierda mientras simultáneamente estiras la pierna derecha.","Regresa a la posición inicial y repite el movimiento del lado opuesto, llevando el codo izquierdo hacia la rodilla derecha mientras estiras la pierna izquierda.","Continúa alternando lados con un movimiento de pedaleo durante el número de repeticiones deseado."]],["0267","Abdominal con manos arriba","crunch (hands overhead)",2,"abd","abdomen",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Extiende los brazos rectos por encima de la cabeza.","Activando el abdomen, levanta la parte superior del cuerpo del suelo, flexionándote hacia adelante en dirección a las rodillas.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["0443","Codo a rodilla","elbow-to-knee",2,"abd","abdomen",["Comienza tumbado boca arriba con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activa el abdomen y levanta la parte superior del cuerpo del suelo, llevando el codo derecho hacia la rodilla izquierda.","Al mismo tiempo, lleva la rodilla izquierda hacia el codo derecho, creando un movimiento de torsión.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo y extiende las piernas de vuelta a la posición inicial.","Repite el movimiento, esta vez llevando el codo izquierdo hacia la rodilla derecha y la rodilla derecha hacia el codo izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."]],["0459","Patadas de tijera","flutter kicks",2,"abd","glúteos",["Túmbate boca arriba con las piernas extendidas y las manos a los costados.","Activa el core y levanta las piernas del suelo unos 15 centímetros.","Manteniendo las piernas rectas, alterna levantando una pierna ligeramente más alto que la otra.","Continúa este movimiento de aleteo durante el número de repeticiones deseado."]],["0872","Abdominal inverso","reverse crunch",2,"abd","abdomen",["Túmbate boca arriba con los brazos extendidos a los lados del cuerpo.","Flexiona las rodillas y levanta los pies del suelo, llevando los muslos perpendiculares al suelo.","Contrae el abdomen y eleva las caderas del suelo, llevando las rodillas hacia el pecho.","Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["0687","Giro ruso","russian twist",2,"abd","abdomen",["Siéntate en el suelo con las rodillas flexionadas y los pies apoyados en el suelo.","Inclínate ligeramente hacia atrás manteniendo la espalda recta y el core activado.","Junta las manos frente al pecho o sujeta una pesa si lo deseas.","Levanta los pies del suelo, equilibrándote sobre los isquiones.","Gira el torso hacia la derecha, llevando las manos o la pesa hacia el lado derecho del cuerpo.","Haz una pausa por un momento, luego gira el torso hacia la izquierda, llevando las manos o la pesa hacia el lado izquierdo del cuerpo.","Continúa alternando lados durante el número de repeticiones deseado."]],["1495","Abdominal oblicuo alterno","oblique crunch v. 2",2,"abd","abdomen",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.","Activa el abdomen y levanta las escápulas del suelo, rotando el torso hacia un lado.","Haz una pausa por un momento y luego baja las escápulas de nuevo a la posición inicial.","Repite del otro lado.","Continúa alternando lados durante el número de repeticiones deseado."]],["3640","Abdominal con toque de rodilla","knee touch crunch",2,"abd","abdomen",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta los omóplatos del suelo y extiende la mano derecha hacia la rodilla izquierda.","Vuelve a la posición inicial y repite, esta vez extendiendo la mano izquierda hacia la rodilla derecha.","Continúa alternando lados durante el número de repeticiones deseado."]],["0871","Abdominal encogido","tuck crunch",2,"abd","abdomen",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta los omóplatos del suelo y lleva las rodillas hacia el pecho, curvando al mismo tiempo la parte superior del cuerpo hacia las rodillas.","Haz una pausa de un momento en la parte superior, luego baja lentamente los omóplatos y extiende las piernas de nuevo a la posición inicial.","Repite el número de repeticiones deseado."]],["0260","Capullos","cocoons",2,"abd","abdomen",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["0469","Abdominal de ingle","groin crunch",2,"abd","abdomen",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta las piernas del suelo, llevando las rodillas hacia el pecho.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["2312","Codo a rodilla acostado","lying elbow to knee",2,"abd","abdomen",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activa el abdomen y levanta la parte superior del cuerpo del suelo, llevando el codo derecho hacia la rodilla izquierda.","Al mismo tiempo, extiende la pierna derecha en línea recta y levántala del suelo.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite el movimiento, esta vez llevando el codo izquierdo hacia la rodilla derecha y extendiendo la pierna izquierda.","Continúa alternando lados durante el número de repeticiones deseado."]],["0865","Elevación de piernas y cadera acostado","lying leg-hip raise",2,"abd","abdomen",["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.","Coloca las manos debajo de los glúteos como apoyo.","Activa el core y levanta las piernas del suelo, elevándolas hacia el techo.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["0735","Abdominal completo","sit-up v. 2",2,"abd","abdomen",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["3679","Abdominal con brazos en el pecho","sit-up with arms on chest",2,"abd","abdomen",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Cruza los brazos sobre el pecho.","Contrayendo el abdomen, levanta la parte superior del cuerpo del suelo hacia las rodillas.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["2429","Abdominal de rana","frog crunch",2,"abd","abdomen",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que el torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["3433","Patadas de nadador","swimmer kicks v. 2 (male)",2,"abd","glúteos",["Túmbate boca abajo sobre una esterilla con los brazos extendidos por encima de la cabeza.","Activa el core y levanta el pecho y las piernas del suelo al mismo tiempo.","Mueve las piernas hacia arriba y hacia abajo con un movimiento de aleteo, como si estuvieras nadando.","Continúa el movimiento de patada el número de repeticiones deseado.","Baja el pecho y las piernas de nuevo a la posición inicial."]],["0634","Abdominal con bajada lenta","negative crunch",3,"abd","abdomen",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["2802","Elevación de piernas con giro","twisted leg raise",3,"abd","abdomen",["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.","Coloca las manos debajo de los glúteos como apoyo.","Activa el abdomen y levanta ambas piernas del suelo, manteniéndolas rectas.","Mientras levantas las piernas, gira las caderas hacia un lado, llevando las piernas hacia el hombro opuesto.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el movimiento, esta vez girando las caderas hacia el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."]],["3239","Plancha de rodillas con toque de hombro","kneeling plank tap shoulder (male)",1,"core","abdomen",["Comienza en posición de rodillas con las manos en el suelo, separadas a la altura de los hombros.","Extiende las piernas hacia atrás, apoyándote en los dedos de los pies, y levanta el cuerpo a una posición de plancha.","Manteniendo el core activado y las caderas estables, levanta una mano del suelo y toca el hombro opuesto.","Devuelve la mano al suelo y repite con la otra mano.","Continúa alternando lados durante el número de repeticiones deseado."]],["3544","Plancha lateral inclinada","bodyweight incline side plank",2,"core","abdomen",["Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra.","Coloca el antebrazo en el suelo justo debajo del hombro, con el codo flexionado en un ángulo de 90 grados.","Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies.","Mantén esta posición durante el tiempo deseado.","Baja las caderas de nuevo al suelo y repite hacia el otro lado."]],["0705","Puente lateral","side bridge v. 2",2,"core","abdomen",["Túmbate de lado con las piernas extendidas y una sobre la otra.","Coloca el antebrazo en el suelo justo debajo del hombro, con el codo flexionado en un ángulo de 90 grados.","Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies.","Mantén esta posición durante el tiempo deseado.","Baja las caderas de vuelta a la posición inicial.","Repite del otro lado."]],["3699","Toque de hombro en plancha","shoulder tap",2,"core","abdomen",["Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.","Activa el core y levanta la mano derecha del suelo, extendiéndola para tocar el hombro izquierdo.","Coloca la mano derecha de nuevo en el suelo y repite tocando el hombro derecho con la mano izquierda.","Continúa alternando los toques de hombro mientras mantienes las caderas y el torso estables.","Repite el número de repeticiones deseado."]],["1471","Gusano caminante","inchworm",2,"core","abdomen",["Comienza de pie con los pies separados a la altura de las caderas.","Inclínate hacia adelante desde la cintura y coloca las manos en el suelo frente a ti.","Camina con las manos hacia adelante hasta quedar en posición de plancha alta, con el cuerpo en línea recta de la cabeza a los pies.","Haz una pausa breve, luego camina con las manos de vuelta hacia los pies, manteniendo las piernas lo más rectas posible.","Cuando las manos lleguen a los pies, ponte de pie de nuevo en la posición inicial.","Repite el número de repeticiones deseado."]],["0464","Plancha frontal con giro","front plank with twist",3,"core","abdomen",["Comienza en posición de plancha alta con las manos directamente debajo de los hombros y el cuerpo en línea recta de la cabeza a los pies.","Activa el core y los glúteos para mantener una posición estable.","Gira el torso hacia la derecha, levantando el brazo derecho y extendiéndolo hacia el techo.","Mantén las caderas y las piernas estables mientras giras.","Mantén la posición por un momento, luego regresa a la posición inicial.","Repite el giro hacia el lado izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."]],["3663","Plancha inversa con elevación de pierna","reverse plank with leg lift",3,"core","abdomen",["Siéntate en el suelo con las piernas extendidas frente a ti y las manos apoyadas en el suelo detrás de ti, con los dedos apuntando hacia los pies.","Presiona con las manos y levanta las caderas del suelo, llegando a una posición de plancha inversa.","Activa el core y levanta una pierna del suelo, extendiéndola recta hacia el techo.","Mantén la posición por un momento y luego baja la pierna de nuevo.","Repite con la otra pierna.","Continúa alternando las piernas durante el número de repeticiones deseado."]],["3360","Caminata de oso","bear crawl",3,"core","sistema cardiovascular",["Comienza apoyado sobre manos y rodillas, con las manos justo debajo de los hombros y las rodillas justo debajo de las caderas.","Levanta las rodillas ligeramente del suelo, manteniendo la espalda plana y el core activado.","Mueve la mano derecha y el pie izquierdo hacia adelante simultáneamente, seguido de la mano izquierda y el pie derecho.","Continúa avanzando a gatas, alternando los movimientos de manos y pies.","Mantén un ritmo constante y el core firme durante todo el ejercicio.","Continúa durante la distancia o el tiempo deseado."]],["1775","Plancha lateral con aducción","side plank hip adduction",3,"core","aductores",["Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra.","Apóyate sobre el antebrazo, manteniendo el codo directamente debajo del hombro.","Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies.","Manteniendo la posición de plancha lateral, levanta la pierna de arriba hacia el techo, manteniéndola recta.","Baja lentamente la pierna de nuevo a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]],["3470","Zancada al frente","forward lunge (male)",1,"pier","glúteos",["Ponte de pie con los pies separados a la altura de las caderas y las manos en las caderas.","Da un paso grande hacia adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.","Dobla la rodilla derecha hasta unos 90 grados, manteniendo la rodilla alineada con el tobillo.","Empuja con el pie derecho y vuelve a la posición inicial.","Repite con la pierna izquierda, alternando los lados durante el número de repeticiones deseado."]],["3221","Medias sentadillas","half knee bends (male)",1,"pier","sistema cardiovascular",["Ponte de pie con los pies separados a la altura de los hombros.","Dobla las rodillas y baja el cuerpo como si te fueras a sentar en una silla.","Mantén el pecho elevado y el peso en los talones.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."]],["3132","Sentadilla con apoyo","potty squat with support",1,"pier","glúteos",["Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.","Sujétate de un apoyo estable, como una silla o una pared, para mantener el equilibrio.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.","Mantén el pecho hacia arriba y la espalda recta durante todo el movimiento.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."]],["1373","Elevación de talones","bodyweight standing calf raise",1,"pier","pantorrillas",["Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante.","Coloca las manos sobre una pared o superficie estable para mantener el equilibrio.","Levanta lentamente los talones del suelo, llevando el peso del cuerpo hacia las puntas de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["3013","Puente de glúteos en el piso","low glute bridge on floor",1,"pier","glúteos",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca los brazos a los lados del cuerpo, con las palmas hacia abajo.","Activa los glúteos y el core, y luego eleva las caderas del suelo hasta que tu cuerpo forme una línea recta desde las rodillas hasta los hombros.","Haz una pausa breve en la parte alta, apretando los glúteos.","Baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["0484","Elevación de cadera con rodillas dobladas","hip raise (bent knee)",1,"pier","abdomen",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos a los lados, con las palmas hacia abajo.","Activa el core y los glúteos, luego levanta las caderas del suelo hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.","Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["0710","Abducción de cadera de lado","side hip abduction",1,"pier","abductores",["Ponte de pie con los pies separados a la altura de los hombros y las manos en las caderas.","Traslada el peso a una pierna y levanta la pierna opuesta hacia el lado, manteniéndola recta.","Haz una pausa por un momento en la posición alta, luego baja lentamente la pierna de nuevo a la posición inicial.","Repite del otro lado.","Continúa alternando lados durante el número de repeticiones deseado."]],["1427","Abducción de pierna recta","straight leg outer hip abductor",1,"pier","abductores",["Túmbate de lado con las piernas rectas y apiladas una sobre la otra.","Coloca el brazo de abajo bajo la cabeza para apoyarte.","Activa el core y levanta la pierna superior lo más alto posible sin rotar las caderas ni inclinarte hacia atrás.","Haz una pausa por un momento en la posición alta, luego baja lentamente la pierna de nuevo a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]],["1687","Paso atrás con alcance arriba","posterior step to overhead reach",1,"pier","abdomen",["Ponte de pie con los pies separados a la altura de las caderas y los brazos a los lados del cuerpo.","Da un paso hacia atrás con el pie derecho, apoyándote en la punta del pie.","Flexiona la rodilla izquierda y baja el cuerpo a una posición de zancada.","Mientras bajas a la zancada, lleva simultáneamente los brazos por encima de la cabeza.","Haz una pausa por un momento en la parte baja de la zancada y luego vuelve a la posición inicial empujando con el talón izquierdo y llevando el pie derecho hacia adelante.","Repite el movimiento hacia el otro lado, retrocediendo con el pie izquierdo y flexionando la rodilla derecha.","Continúa alternando lados durante el número de repeticiones deseado."]],["1685","Sentadilla con alcance arriba","squat to overhead reach",1,"pier","cuádriceps",["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.","Mientras te levantas de la sentadilla, extiende los brazos por encima de la cabeza, alcanzando hacia el techo.","Vuelve a la posición inicial bajando los brazos y flexionando las rodillas para volver a hacer la sentadilla.","Repite el número de repeticiones deseado."]],["0795","Flexión de pierna de pie","standing single leg curl",1,"pier","isquiotibiales",["Ponte de pie con los pies separados a la altura de las caderas y las manos en las caderas.","Traslada tu peso a la pierna izquierda y levanta el pie derecho del suelo, flexionando la rodilla.","Curva lentamente el talón derecho hacia los glúteos, contrayendo el isquiotibial.","Haz una pausa de un momento en la parte superior y luego baja lentamente el pie derecho de nuevo a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."]],["1460","Zancada caminando","walking lunge",2,"pier","glúteos",["Ponte de pie con los pies separados a la altura de los hombros.","Da un paso adelante con la pierna derecha, bajando el cuerpo a una posición de zancada.","Mantén el torso erguido y la rodilla delantera alineada con el tobillo.","Empújate con el pie derecho y lleva el pie izquierdo hacia adelante, entrando en una posición de zancada con la pierna izquierda.","Continúa alternando las piernas y avanzando, manteniendo un ritmo controlado y constante.","Repite el número de repeticiones deseado."]],["3769","Sentadilla reverencia","curtsey squat",2,"pier","glúteos",["Ponte de pie con los pies separados a la altura de los hombros.","Da un paso en diagonal hacia atrás y a través de tu cuerpo con el pie derecho, cruzándolo detrás de la pierna izquierda.","Flexiona ambas rodillas como si hicieras una reverencia, bajando el cuerpo hacia el suelo.","Mantén el torso erguido y el peso sobre el pie delantero.","Empuja con el pie delantero para regresar a la posición inicial.","Repite en el otro lado, dando un paso en diagonal hacia atrás y a través de tu cuerpo con el pie izquierdo."]],["2368","Sentadilla dividida","split squats",2,"pier","cuádriceps",["Ponte de pie con los pies separados a la altura de los hombros.","Da un paso adelante con un pie y colócalo aproximadamente a dos pies de distancia por delante del otro pie.","Baja el cuerpo flexionando las rodillas y las caderas, manteniendo la espalda recta.","Sigue bajando hasta que el muslo delantero quede paralelo al suelo y la rodilla trasera quede justo por encima del suelo.","Haz una pausa breve, luego empuja con el talón delantero para volver a la posición inicial.","Repite el número de repeticiones deseado y luego cambia de pierna y repite."]],["3119","Sentadilla profunda","potty squat",2,"pier","abdomen",["Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.","Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás como si te sentaras en una silla.","Mantén el pecho hacia arriba y la espalda recta durante todo el movimiento.","Baja hasta que los muslos queden paralelos al suelo o hasta donde puedas llegar cómodamente.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."]],["1490","Elevación de talones en escalón","standing calf raise (on a staircase)",2,"pier","pantorrillas",["Ponte de pie en el borde de un escalón o una plataforma firme, con los talones colgando y la punta de los pies sobre el escalón.","Sujétate de una baranda o pared para mantener el equilibrio si es necesario.","Levanta lentamente los talones lo más alto posible, elevando el peso de tu cuerpo sobre la punta de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["3561","Marcha en puente de glúteos","glute bridge march",2,"pier","glúteos",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Activa los glúteos y levanta las caderas del suelo, formando una línea recta desde las rodillas hasta los hombros.","Manteniendo las caderas elevadas, levanta un pie del suelo y lleva la rodilla hacia el pecho.","Baja el pie de nuevo al suelo y repite el movimiento con la otra pierna.","Continúa alternando las piernas con un movimiento de marcha mientras mantienes la posición de puente.","Repite el número de repeticiones deseado."]],["3667","Aducción de cadera de lado","side lying hip adduction (male)",2,"pier","aductores",["Túmbate de lado con las piernas rectas y apiladas una sobre la otra.","Coloca el brazo de abajo bajo la cabeza para apoyarte.","Activa los aductores y levanta la pierna de arriba lo más alto posible sin rotar las caderas ni inclinarte hacia atrás.","Haz una pausa por un momento en la posición alta, luego baja lentamente la pierna de nuevo a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."]],["1686","Sentadilla con alcance y giro","squat to overhead reach with twist",2,"pier","cuádriceps",["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.","Mientras te levantas de la sentadilla, eleva los brazos por encima de la cabeza y gira el torso hacia un lado.","Vuelve a la posición inicial y repite la sentadilla, esta vez girando el torso hacia el lado opuesto.","Continúa alternando los lados en cada repetición de la sentadilla."]],["1688","Zancada con giro","lunge with twist",2,"pier","abdomen",["Comienza de pie con los pies separados a la altura de los hombros.","Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.","Al hacer la zancada, gira el torso hacia la derecha, llevando el codo izquierdo hacia la rodilla derecha.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite hacia el otro lado, dando un paso adelante con el pie izquierdo y girando el torso hacia la izquierda.","Continúa alternando lados durante el número de repeticiones deseado."]],["1466","Elevación de cadera con giro","twist hip lift",2,"pier","glúteos",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos a los lados para mayor apoyo.","Activa los glúteos y levanta las caderas del suelo, formando una línea recta desde las rodillas hasta los hombros.","Manteniendo las caderas elevadas, gira la parte inferior del cuerpo hacia el lado derecho, llevando las rodillas hacia el suelo.","Vuelve a la posición inicial y repite el giro hacia el lado izquierdo.","Continúa alternando los giros el número de repeticiones deseado."]],["0284","Elevación de talones a una pierna","donkey calf raise",3,"pier","pantorrillas",["Ponte de pie con las puntas de los pies sobre una superficie elevada, como un escalón o un bloque.","Coloca las manos en un soporte estable, como una pared o un pasamanos, para mantener el equilibrio.","Levanta los talones lo más alto posible, elevando el peso de tu cuerpo sobre las puntas de los pies.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["3645","Puente a una pierna","single leg bridge with outstretched leg",3,"pier","glúteos",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Extiende una pierna recta hacia delante.","Activa los glúteos y levanta las caderas del suelo, formando una línea recta desde las rodillas hasta los hombros.","Mantén la posición alta por un momento, luego baja lentamente las caderas de nuevo a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."]],["0668","Puente inverso en declive","rear decline bridge",3,"pier","glúteos",["Túmbate boca arriba con los pies planos en el suelo y las rodillas flexionadas.","Coloca los brazos a los lados del cuerpo con las palmas hacia abajo.","Activa los glúteos y los isquiotibiales, y eleva las caderas del suelo hasta que tu cuerpo forme una línea recta desde las rodillas hasta los hombros.","Mantén esta posición durante unos segundos y luego baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["3672","Paso adelante y atrás","back and forth step",1,"card","sistema cardiovascular",["Ponte de pie con los pies separados a la altura de los hombros.","Da un paso adelante con el pie derecho, flexionando la rodilla y bajando el cuerpo hacia una posición de zancada.","Empuja con el pie derecho y da un paso atrás para regresar a la posición inicial.","Repite el movimiento con el pie izquierdo, alternando las piernas en cada paso.","Continúa dando pasos hacia adelante y hacia atrás, manteniendo un ritmo constante.","Repite durante la duración o el número de repeticiones deseado."]],["3636","Rodillas altas contra la pared","high knee against wall",1,"card","sistema cardiovascular",["Ponte de pie frente a una pared con los pies separados a la altura de las caderas.","Coloca las manos en la pared para mayor apoyo.","Activa el core y levanta la rodilla derecha hacia el pecho, mientras mantienes el pie izquierdo en el suelo.","Cambia rápidamente de pierna, llevando la rodilla izquierda hacia el pecho y bajando el pie derecho de nuevo.","Continúa alternando las piernas con un movimiento de carrera, llevando las rodillas lo más alto posible.","Mantén un ritmo rápido y la parte superior del cuerpo estable durante todo el ejercicio.","Repite durante la duración o el número de repeticiones deseado."]],["3671","Paso de esquí","ski step",2,"card","sistema cardiovascular",["Ponte de pie con los pies separados a la altura de los hombros.","Dobla ligeramente las rodillas y mantén la espalda recta.","Salta hacia la derecha, aterrizando sobre el pie derecho mientras balanceas la pierna izquierda detrás de la pierna derecha.","Salta inmediatamente hacia la izquierda, aterrizando sobre el pie izquierdo mientras balanceas la pierna derecha detrás de la pierna izquierda.","Continúa alternando los saltos de lado a lado, imitando un movimiento de esquí.","Repite el número de repeticiones deseado."]],["3655","Zancada con rodillas altas","walking high knees lunge",3,"card","sistema cardiovascular",["Ponte de pie con los pies separados a la altura de la cadera.","Levanta la rodilla derecha hacia el pecho lo más alto que puedas mientras mantienes el equilibrio sobre la pierna izquierda.","Da un paso adelante con el pie derecho y baja el cuerpo a una posición de zancada, flexionando ambas rodillas a un ángulo de 90 grados.","Empújate con el pie derecho y lleva la rodilla izquierda hacia el pecho.","Da un paso adelante con el pie izquierdo y baja el cuerpo a una posición de zancada.","Continúa alternando las piernas y avanzando con zancadas, manteniendo el core activado y un ritmo constante.","Repite el número de repeticiones deseado."]],["0659","Flexión en la pared","push-up (wall)",1,"push","pecho",["Ponte de pie frente a una pared, a una distancia aproximada de un brazo.","Coloca las manos en la pared a la altura de los hombros, un poco más separadas que la anchura de los hombros.","Da un paso atrás, manteniendo el cuerpo recto y los pies separados a la altura de las caderas.","Flexiona los codos y baja el pecho hacia la pared, manteniendo el cuerpo en línea recta.","Empuja de vuelta a la posición inicial, estirando los brazos.","Repite el número de repeticiones deseado."]],["0658","Flexión en la pared (variante)","push-up (wall) v. 2",1,"push","pecho",["Ponte de pie frente a una pared, a una distancia aproximada de un brazo.","Coloca las manos en la pared a la altura de los hombros, un poco más separadas que la anchura de los hombros.","Retrocede con los pies, manteniéndolos separados a la altura de las caderas.","Activa el core y mantén el cuerpo en línea recta desde la cabeza hasta los talones.","Flexiona los codos y baja el pecho hacia la pared, manteniendo el cuerpo recto.","Haz una pausa por un momento y luego empújate de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["0493","Flexión inclinada","incline push-up",1,"push","pecho",["Coloca las manos sobre una superficie elevada, como un banco o un escalón, ligeramente más separadas que la altura de los hombros.","Extiende las piernas detrás de ti, apoyándote en la punta de los pies, formando una línea recta desde la cabeza hasta los talones.","Baja el pecho hacia la superficie elevada doblando los codos, manteniendo el cuerpo en línea recta.","Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."]],["3211","Flexión de rodillas","kneeling push-up (male)",1,"push","pecho",["Comienza arrodillado en el suelo con las manos separadas a la altura de los hombros, los dedos apuntando hacia adelante.","Extiende las piernas hacia atrás, apoyándote en la punta de los pies, de modo que tu cuerpo forme una línea recta desde la cabeza hasta los talones.","Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.","Continúa bajando hasta que el pecho esté justo encima del suelo, luego empuja hacia arriba a la posición inicial enderezando los brazos.","Repite el número de repeticiones deseado."]],["1297","Contracción isométrica de pecho","isometric chest squeeze",1,"push","pecho",["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Extiende los brazos rectos frente a ti, paralelos al suelo, con las palmas una frente a la otra.","Aprieta los músculos del pecho con la mayor fuerza posible, manteniendo los brazos rectos.","Mantén esta posición durante unos segundos, concentrándote en contraer los músculos del pecho.","Suelta la contracción y relaja los músculos del pecho.","Repite el número de repeticiones deseado."]],["0662","Flexión de brazos","push-up",2,"push","pecho",["Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y los pies juntos.","Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniendo el cuerpo en línea recta.","Haz una pausa cuando el pecho esté justo por encima del suelo y luego empújate de vuelta a la posición inicial estirando los brazos.","Repite el número de repeticiones deseado."]],["2398","Flexión cerrada de rodillas","close-grip push-up (on knees)",2,"push","tríceps",["Comienza apoyándote sobre las manos y las rodillas, con las manos separadas a la altura de los hombros y las rodillas separadas a la altura de las caderas.","Baja la parte superior del cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.","Haz una pausa breve cuando tu pecho esté justo por encima del suelo.","Empuja con las palmas para estirar los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."]],["1311","Flexión con manos abiertas","wide hand push up",2,"push","pecho",["Comienza en una posición de plancha alta con las manos más separadas que la anchura de los hombros.","Mantén el cuerpo en línea recta de la cabeza a los pies.","Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."]],["3145","Flexión con protracción","push-up plus",2,"push","pecho",["Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y el cuerpo en línea recta desde la cabeza hasta los talones.","Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.","Cuando el pecho esté justo por encima del suelo, empuja con las manos para extender los brazos y levantar la parte superior del cuerpo.","En la parte alta del movimiento, separa las escápulas empujando la parte superior de la espalda hacia el techo.","Haz una pausa por un momento y luego invierte el movimiento juntando las escápulas y bajando el cuerpo de nuevo a la posición inicial.","Repite el número de repeticiones deseado."]],["3021","Flexión de escápulas","scapula push-up",2,"push","serrato",["Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.","Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo.","A medida que bajas, junta las escápulas y empuja el pecho hacia delante.","Haz una pausa por un momento en la posición baja, luego empuja de nuevo hacia arriba hasta la posición inicial.","Repite el número de repeticiones deseado."]],["3011","Flexión de escápulas inclinada","incline scapula push up",2,"push","serrato",["Coloca un banco inclinado a un ángulo de 45 grados.","Coloca las manos en el banco, ligeramente más separadas que la altura de los hombros.","Coloca los pies en el suelo, separados a la altura de las caderas.","Baja el pecho hacia el banco, manteniendo los codos pegados al cuerpo.","Mientras bajas, retrae los omóplatos, apretándolos entre sí.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."]],["0816","Press de tríceps","triceps press",2,"push","tríceps",["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Extiende los brazos rectos frente a ti, paralelos al suelo.","Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la parte superior de los brazos cerca de los costados.","Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["1771","Extensión de tríceps de rodillas","bodyweight kneeling triceps extension",2,"push","tríceps",["Ponte de rodillas en el suelo con las rodillas separadas a la altura de las caderas.","Coloca las manos en el suelo frente a ti, separadas a la altura de los hombros, con los dedos apuntando hacia adelante.","Extiende las piernas rectas detrás de ti, equilibrándote sobre las puntas de los pies y las manos, formando una línea recta desde la cabeza hasta los talones.","Flexiona los codos y baja la parte superior del cuerpo hacia el suelo, manteniendo los codos cerca del cuerpo.","Haz una pausa breve en la posición más baja, luego empuja con las manos para extender los brazos y volver a la posición inicial.","Repite el número de repeticiones deseado."]],["1772","Flexión inversa con elevación de codos","elbow lift - reverse push-up",2,"push","espalda alta",["Comienza tumbado boca abajo en el suelo con las piernas extendidas y las manos colocadas justo debajo de los hombros.","Activa el core y presiona con las palmas para levantar la parte superior del cuerpo del suelo, manteniendo los codos cerca de los costados.","Haz una pausa por un momento en la parte superior, apretando los músculos de la espalda alta.","Baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["0259","Flexión cerrada","close-grip push-up",3,"push","tríceps",["Comienza en posición de plancha alta con las manos juntas, directamente debajo de los hombros.","Activa el core y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."]],["0283","Flexión diamante","diamond push-up",3,"push","tríceps",["Comienza en posición de plancha alta con las manos juntas, formando una figura de diamante con los pulgares y los índices.","Mantén el cuerpo en línea recta de la cabeza a los pies, activando el core y los glúteos.","Baja el pecho hacia la figura de diamante formada por tus manos, manteniendo los codos cerca del cuerpo.","Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["0279","Flexión en declive","decline push-up",3,"push","pecho",["Coloca las manos en el suelo un poco más separadas que el ancho de los hombros, con los pies elevados sobre una superficie estable.","Mantén el cuerpo en línea recta de la cabeza a los pies, activando los músculos del core.","Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."]],["1467","Flexión sobre antebrazos","push-up on lower arms",3,"push","tríceps",["Comienza en posición de plancha con los antebrazos en el suelo y los codos directamente debajo de los hombros.","Activa el core y mantén el cuerpo en línea recta de la cabeza a los pies.","Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo.","Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."]],["0699","Flexión con toque de hombro","shoulder tap push-up",3,"push","pecho",["Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y el cuerpo en línea recta desde la cabeza hasta los talones.","Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.","Mientras empujas hacia arriba, levanta la mano derecha del suelo y toca el hombro izquierdo.","Vuelve a colocar la mano derecha en el suelo y repite la flexión, esta vez levantando la mano izquierda y tocando el hombro derecho.","Continúa alternando los toques de hombro en cada repetición de la flexión.","Mantén el core estable y evita una rotación excesiva de la cadera durante todo el ejercicio.","Repite el número de repeticiones deseado."]],["1368","Círculos de tobillo","ankle circles",0,"est","pantorrillas",["Siéntate en el suelo con las piernas extendidas frente a ti.","Levanta una pierna del suelo y rota el tobillo con un movimiento circular.","Realiza el número de círculos deseado en una dirección, luego cambia a la dirección contraria.","Repite con la otra pierna."]],["1428","Círculos de muñeca","wrist circles",0,"est","antebrazos",["Extiende los brazos rectos frente a ti.","Cierra ambas manos en un puño.","Gira las muñecas en un movimiento circular, manteniendo los brazos quietos.","Continúa los círculos de muñeca el número de repeticiones deseado."]],["1403","Estiramiento lateral de cuello","neck side stretch",0,"est","elevador de la escápula",["Ponte de pie o siéntate erguido con los hombros relajados.","Inclina la cabeza hacia un lado, llevando la oreja hacia el hombro.","Mantén el estiramiento durante 15-30 segundos.","Repite del otro lado.","Realiza de 2 a 4 series por cada lado."]],["0716","Estiramiento de cuello con empuje lateral","side push neck stretch",0,"est","elevador de la escápula",["Ponte de pie o siéntate erguido con los hombros relajados.","Inclina la cabeza hacia la derecha, llevando la oreja derecha hacia el hombro derecho.","Coloca la mano derecha en el lado izquierdo de la cabeza y aplica una presión suave para aumentar el estiramiento.","Mantén el estiramiento durante 15-30 segundos.","Repite hacia el otro lado, inclinando la cabeza hacia la izquierda y aplicando presión con la mano izquierda.","Repite el estiramiento 2-3 veces en cada lado."]],["1405","Estiramiento de pectoral y espalda","back pec stretch",0,"est","dorsales",["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.","Extiende los brazos rectos frente a ti, paralelos al suelo.","Cruza los brazos frente al cuerpo, con el brazo derecho sobre el brazo izquierdo.","Entrelaza los dedos y gira las palmas alejándolas del cuerpo.","Levanta lentamente los brazos hacia arriba y alejándolos del cuerpo, sintiendo un estiramiento en la espalda y el pecho.","Mantén el estiramiento durante 15-30 segundos, luego suelta.","Repite del lado opuesto."]],["1271","Estiramiento de pecho y hombro","chest and front of shoulder stretch",0,"est","pecho",["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.","Extiende los brazos rectos frente a ti a la altura de los hombros.","Cruza los brazos frente a tu cuerpo, con el brazo derecho sobre el brazo izquierdo.","Entrelaza los dedos y presiona las palmas entre sí.","Aprieta suavemente los omóplatos entre sí y empuja las manos hacia adelante, sintiendo un estiramiento en el pecho y la parte delantera de los hombros.","Mantén el estiramiento durante 20-30 segundos, luego suelta.","Repite el número de repeticiones deseado."]],["1167","Estiramiento dinámico de pecho","dynamic chest stretch (male)",0,"est","pecho",["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.","Extiende los brazos hacia los lados, paralelos al suelo.","Lleva lentamente los brazos hacia adelante, cruzándolos frente al cuerpo.","Siente el estiramiento en los músculos del pecho.","Mantén el estiramiento durante 10-30 segundos.","Vuelve a la posición inicial y repite el número de repeticiones deseado."]],["0643","Estiramiento de tríceps sobre la cabeza","overhead triceps stretch",0,"est","tríceps",["Ponte de pie o siéntate erguido con los pies separados a la altura de los hombros.","Extiende un brazo por encima de la cabeza, flexionando el codo de modo que la mano llegue hacia la escápula opuesta.","Con la otra mano, tira suavemente del codo del brazo extendido hacia el lado opuesto de la cabeza, sintiendo un estiramiento en el tríceps.","Mantén el estiramiento durante 15-30 segundos, luego suelta.","Repite del otro lado."]],["0817","Estiramiento de tríceps","triceps stretch",0,"est","tríceps",["Ponte de pie o siéntate erguido con la espalda recta.","Extiende un brazo por encima de la cabeza, flexionándolo por el codo.","Coloca la mano opuesta sobre el codo flexionado y tira de él suavemente hacia tu cabeza.","Mantén el estiramiento de 15 a 30 segundos, sintiendo un estiramiento suave en el tríceps.","Suelta el estiramiento y repite con el otro brazo."]],["0669","Estiramiento de hombro posterior","rear deltoid stretch",0,"est","hombros",["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.","Extiende el brazo derecho a través del pecho, colocando la mano izquierda sobre el codo derecho.","Tira suavemente del brazo derecho hacia el hombro izquierdo, sintiendo un estiramiento en el hombro derecho.","Mantén el estiramiento durante 15-30 segundos, luego suelta.","Repite del otro lado."]],["1346","Estiramiento de dorsales de rodillas","kneeling lat stretch",0,"est","dorsales",["Arrodíllate en el suelo con las rodillas separadas a la altura de las caderas y los dedos de los pies apuntando hacia atrás.","Extiende los brazos por encima de la cabeza y entrelaza los dedos.","Manteniendo la espalda recta, inclínate lentamente hacia el lado derecho, sintiendo un estiramiento en el dorsal izquierdo.","Mantén el estiramiento durante 20-30 segundos, luego vuelve a la posición inicial.","Repite el estiramiento en el lado izquierdo, inclinándote hacia la izquierda y sintiendo un estiramiento en el dorsal derecho.","Continúa alternando lados durante el número de repeticiones deseado."]],["1365","Estiramiento de espalda alta","upper back stretch",0,"est","espalda alta",["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.","Extiende los brazos rectos frente a ti, paralelos al suelo.","Entrelaza los dedos y gira las palmas alejándolas de tu cuerpo.","Eleva lentamente los brazos por encima de la cabeza, manteniéndolos rectos y paralelos entre sí.","Mientras elevas los brazos, aprieta los omóplatos entre sí.","Mantén el estiramiento de 15 a 30 segundos, luego suelta y repite."]],["1363","Estiramiento de columna","spine stretch",0,"est","columna",["Siéntate en el suelo con las piernas extendidas frente a ti.","Coloca las manos en el suelo detrás de ti, con los dedos apuntando hacia tu cuerpo.","Activa el core e inclínate lentamente hacia atrás, manteniendo la espalda recta.","Sigue inclinándote hacia atrás hasta que sientas un estiramiento en la columna.","Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."]],["2329","Giro de columna","spine twist",0,"est","abdomen",["Siéntate en el suelo con las piernas extendidas frente a ti.","Dobla las rodillas y coloca los pies planos sobre el suelo, separados a la altura de la cadera.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activa el abdomen y gira lentamente el torso hacia la derecha, llevando el codo derecho hacia la rodilla izquierda.","Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.","Repite el giro hacia el lado izquierdo, llevando el codo izquierdo hacia la rodilla derecha.","Continúa alternando lados durante el número de repeticiones deseado."]],["0690","Estiramiento de espalda baja sentado","seated lower back stretch",0,"est","dorsales",["Siéntate en el borde de una silla con los pies planos sobre el suelo.","Coloca las manos sobre los muslos o a los lados de la silla para apoyarte.","Inclínate lentamente hacia delante desde la cadera, manteniendo la espalda recta.","Siente el estiramiento en la zona lumbar y mantén la posición durante 20-30 segundos.","Regresa lentamente a la posición inicial y repite el número de repeticiones deseado."]],["1424","Estiramiento de glúteo sentado","seated glute stretch",0,"est","glúteos",["Siéntate en el suelo con las piernas extendidas frente a ti.","Dobla la rodilla derecha y cruza el tobillo derecho sobre el muslo izquierdo.","Coloca la mano derecha en el suelo detrás de ti para apoyarte.","Con la mano izquierda, presiona suavemente la rodilla derecha para profundizar el estiramiento.","Mantén el estiramiento durante 30 segundos a 1 minuto.","Cambia de lado y repite."]],["2567","Estiramiento de piriforme sentado","seated piriformis stretch",0,"est","glúteos",["Siéntate en el suelo con las piernas extendidas frente a ti.","Dobla la rodilla derecha y coloca el pie derecho en la parte exterior de la rodilla izquierda.","Coloca el codo izquierdo en la parte exterior de la rodilla derecha y gira suavemente el torso hacia la derecha.","Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite."]],["1494","Postura de mariposa","butterfly yoga pose",0,"est","aductores",["Siéntate en el suelo con las piernas extendidas frente a ti.","Flexiona las rodillas y junta las plantas de los pies, dejando que las rodillas caigan hacia los lados.","Sujétate los tobillos o los pies con las manos.","Siéntate erguido y alarga la columna.","Presiona suavemente las rodillas hacia el suelo, sintiendo un estiramiento en la parte interna de los muslos.","Mantén esta posición durante unas cuantas respiraciones.","Para liberar, lleva lentamente las rodillas hacia arriba de nuevo y extiende las piernas."]],["1390","Estiramiento de pantorrilla sentado","seated calf stretch (male)",0,"est","pantorrillas",["Siéntate en el borde de una silla o banco con los pies planos sobre el suelo.","Extiende una pierna recta frente a ti, manteniendo el talón en el suelo.","Inclínate ligeramente hacia delante, sintiendo un estiramiento en la pantorrilla.","Mantén el estiramiento durante 20-30 segundos.","Cambia de pierna y repite el estiramiento."]],["1377","Estiramiento de pantorrilla contra la pared","calf stretch with hands against wall",0,"est","pantorrillas",["Ponte de pie frente a una pared con los pies separados a la altura de las caderas.","Coloca las manos contra la pared a la altura de los hombros.","Da un paso atrás con el pie derecho, manteniendo el talón en el suelo y la pierna recta.","Flexiona la rodilla izquierda e inclínate hacia adelante, manteniendo la pierna de atrás recta y el talón en el suelo.","Mantén el estiramiento durante 20-30 segundos.","Cambia de pierna y repite el estiramiento."]],["1512","Estiramiento de cuádriceps en cuatro apoyos","all fours squad stretch",0,"est","cuádriceps",["Comienza apoyado sobre manos y rodillas, con las manos justo debajo de los hombros y las rodillas justo debajo de las caderas.","Extiende una pierna hacia atrás, manteniendo la rodilla flexionada y el pie en flexión.","Baja lentamente las caderas hacia el suelo, sintiendo un estiramiento en los cuádriceps.","Mantén esta posición durante 20-30 segundos.","Cambia de pierna y repite el estiramiento del otro lado."]],["0613","Estiramiento de cuádriceps acostado de lado","lying (side) quads stretch",0,"est","cuádriceps",["Túmbate de lado con las piernas rectas.","Flexiona la pierna de arriba y agarra tu tobillo o pie con la mano.","Tira suavemente del tobillo o del pie hacia los glúteos hasta sentir un estiramiento en los cuádriceps.","Mantén el estiramiento durante 20-30 segundos.","Suelta el estiramiento y repite del otro lado."]],["1418","Abrazo de rodillas al pecho","hug keens to chest",0,"est","glúteos",["Comienza de pie con los pies separados a la altura de los hombros.","Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla.","Al ponerte en cuclillas, lleva las rodillas hacia el pecho y abrázalas con los brazos.","Mantén esta posición por un momento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."]],["1362","Postura de la esfinge","sphinx",0,"est","columna",["Túmbate boca abajo en el suelo con los antebrazos planos sobre el piso y los codos justo debajo de los hombros.","Activa el core y levanta el pecho del suelo, manteniendo los antebrazos y los dedos de los pies en el piso.","Mantén esta posición durante unos segundos, asegurándote de mantener el cuello en una posición neutral.","Baja lentamente el pecho de nuevo a la posición inicial.","Repite el número de repeticiones deseado."]],["1366","Perro mirando hacia arriba","upward facing dog",0,"est","columna",["Túmbate boca abajo en el suelo con las piernas extendidas detrás de ti.","Coloca las manos en el suelo junto a las costillas inferiores, con los dedos apuntando hacia adelante.","Presiona las manos firmemente contra el suelo y estira los brazos, levantando el torso y los muslos del suelo.","Lleva los hombros hacia atrás y hacia abajo, abriendo el pecho y elevando la mirada hacia el techo.","Mantén esta posición durante unas cuantas respiraciones, luego baja lentamente el cuerpo de nuevo a la posición inicial.","Repite el número de repeticiones deseado."]],["1604","El mejor estiramiento del mundo","world greatest stretch",0,"est","isquiotibiales",["Comienza en posición de zancada con el pie derecho adelante y el pie izquierdo atrás.","Coloca las manos en el suelo a ambos lados de tu pie derecho.","Baja la rodilla izquierda hacia el suelo y extiende la pierna derecha, manteniendo el pie derecho plano sobre el suelo.","Gira el torso hacia la derecha, extendiendo el brazo derecho hacia el techo.","Mantén esta posición durante unos segundos, luego vuelve a la posición inicial.","Cambia de lado y repite el estiramiento con el pie izquierdo adelante."]],["0794","Estiramiento lateral de pie","standing lateral stretch",0,"est","dorsales",["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Extiende los brazos hacia los lados, paralelos al suelo.","Inclina lentamente la parte superior del cuerpo hacia un lado, sintiendo un estiramiento en el costado y los dorsales.","Mantén el estiramiento durante 15-30 segundos.","Regresa a la posición inicial y repite del otro lado.","Repite el número de repeticiones deseado."]],["3639","Giro acostado con rodilla doblada","bent knee lying twist (male)",0,"est","glúteos",["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Extiende los brazos hacia los lados, perpendiculares al cuerpo.","Manteniendo las rodillas juntas, bájalas lentamente hacia un lado, intentando tocar el suelo con las rodillas.","Haz una pausa breve, luego activa el core y levanta lentamente las rodillas de vuelta a la posición inicial.","Repite el movimiento hacia el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."]],["2571","Estiramiento de rana mecedora","rocking frog stretch",0,"est","glúteos",["Comienza arrodillándote en el suelo con las rodillas separadas a la altura de las caderas.","Coloca las manos en el suelo frente a ti para mayor apoyo.","Inclínate lentamente hacia adelante, desplazando el peso hacia las manos y extendiendo las piernas detrás de ti.","Mantén la espalda recta y activa los glúteos mientras empujas las caderas hacia atrás y hacia arriba en dirección al techo.","Mantén esta posición durante unos segundos, sintiendo un estiramiento en los glúteos.","Vuelve lentamente a la posición inicial flexionando las rodillas y bajando las caderas de nuevo.","Repite el número de repeticiones deseado."]],["1585","Estiramiento de corredor","runners stretch",0,"est","isquiotibiales",["Ponte de pie con los pies separados a la altura de la cadera.","Da un paso hacia delante con el pie derecho, manteniendo el pie izquierdo firme en el suelo.","Dobla la rodilla derecha y baja el cuerpo, manteniendo la pierna izquierda recta.","Coloca las manos sobre el muslo derecho para apoyarte.","Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite."]],["1548","Estiramiento de pierna extendida en silla","chair leg extended stretch",0,"est","cuádriceps",["Siéntate al borde de una silla con la espalda recta y los pies planos en el suelo.","Extiende una pierna recta frente a ti, manteniendo el talón en el suelo.","Inclínate ligeramente hacia adelante, sintiendo un estiramiento en los cuádriceps.","Mantén esta posición durante 20-30 segundos.","Cambia de pierna y repite el estiramiento."]],["0721","Estiramiento lateral de muñeca","side wrist pull stretch",0,"est","antebrazos",["Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos frente a ti.","Extiende el brazo derecho hacia el lado, paralelo al suelo, con la palma hacia abajo.","Con la mano izquierda, sujeta la mano derecha y tira de ella suavemente hacia tu cuerpo, sintiendo un estiramiento en el antebrazo derecho.","Mantén el estiramiento durante 15-30 segundos, luego suelta.","Repite del otro lado."]],["1358","Estiramiento acostado de lado","side lying floor stretch",0,"est","dorsales",["Túmbate de lado con las piernas rectas y el brazo de abajo extendido recto por encima de la cabeza.","Dobla la rodilla de arriba y coloca el pie en el suelo frente a la pierna de abajo.","Extiende el brazo de arriba por encima de la cabeza y agárrate a algo estable, como una pared o un mueble.","Levanta lentamente la pierna de abajo del suelo, manteniéndola recta, hasta sentir un estiramiento en el costado.","Mantén el estiramiento durante 20-30 segundos, luego baja lentamente la pierna de nuevo.","Repite del otro lado."]]];
